let demoRecordingCount=0,demoRecordingTimer=null,demoRecordingActive=false;
recordingDialog=function(){const box=document.getElementById('modal');box.className='recording-dialog';box.oncancel=null;box.innerHTML=`<div class="record-heading"><span class="input-icon">${icon('teams')}</span><div><h2>Recording setup</h2><p class="sub">Preview speaker-separated transcripts in two languages.</p></div></div><div class="form"><label class="field">Recording title<input id="recordTitle" value="Product requirements discussion"></label><label class="field">Spoken language<select><option>English & Japanese</option><option>English</option><option>日本語</option></select></label><div class="notice">Demo mode · Uses sample audio transcript text. No microphone audio is captured.</div></div><div class="form-footer"><button onclick="document.getElementById('modal').close()">Cancel</button><button class="primary" onclick="startDemoRecording()">Start recording preview →</button></div>`;box.showModal()};
let demoRecordingTitle='Product requirements discussion';
function startDemoRecording(){demoRecordingTitle=document.getElementById('recordTitle').value.trim()||'Product requirements discussion';document.getElementById('modal').close();demoRecordingCount=1;demoRecordingActive=true;clearInterval(demoRecordingTimer);screen='meetings';history.replaceState(null,'','#meetings');render();window.scrollTo(0,0);demoRecordingTimer=setInterval(()=>{if(!demoRecordingActive)return;demoRecordingCount++;if(demoRecordingCount>=jpMeeting.length){demoRecordingActive=false;clearInterval(demoRecordingTimer)}if(screen==='meetings')render()},2200)}
function stopDemoRecording(){demoRecordingActive=false;clearInterval(demoRecordingTimer);render()}
blueprintPageRoutes.meetings=function(){return appNav()+bpHeading(esc(demoRecordingTitle),'Demo transcript · Speakers are sample participants.',button('New recording','recordingDialog()')+(demoRecordingActive?button('Stop preview','stopDemoRecording()',true):''))+'<div class="notice">'+(demoRecordingActive?'● Demo recording in progress':'Demo recording finished')+' · Sample transcript and translation, not captured audio.</div><div class="bilingual-page">'+[['English',1],['日本語',2]].map(([lang,col])=>'<section class="panel"><div class="panel-title"><h2>'+lang+'</h2><span class="badge blue">'+(col===1?'Transcript':'翻訳')+'</span></div><div class="transcript-feed">'+jpMeeting.slice(0,demoRecordingCount).map((r,i)=>'<article class="speaker-entry"><div><span class="speaker-chip">'+(i+1)+'</span><strong>'+esc(r[0])+'</strong><time>00:'+String(i*8).padStart(2,'0')+'</time></div><p>'+esc(r[col])+'</p></article>').join('')+'</div></section>').join('')+'</div>'};
showSectionVersions=function(){sectionSave();const list=sectionVersions[sectionKey()]||[],box=document.getElementById('modal');box.className='history-dialog';box.oncancel=null;box.innerHTML='<div class="history-heading"><div><h2>Version history</h2><p class="sub">'+esc(sectionTitles[sectionIndex])+'</p></div><button aria-label="Close version history" onclick="document.getElementById(\'modal\').close()">×</button></div><div class="history-body">'+list.slice().reverse().map((v,j)=>'<article class="history-card"><div class="history-card-head"><strong>Version '+(list.length-j)+'</strong>'+(j===0?'<span class="badge blue">Latest saved</span>':'')+'</div><p class="history-meta">'+esc(v.author)+' · '+new Date(v.time).toLocaleString()+'</p><p>'+esc(v.reason)+'</p><details><summary>Preview content</summary><pre>'+esc(v.text||'Empty section')+'</pre></details><div class="page-actions"><button '+(current().approved||j===0?'disabled':'')+' onclick="restoreSectionVersion('+(list.length-1-j)+')">Restore this version</button></div></article>').join('')+'</div><div class="history-footer"><span>History is saved for this browser session.</span><button onclick="document.getElementById(\'modal\').close()">Done</button></div>';box.showModal()};
const originalSrsExport=exportSections;
exportSections=function(){originalSrsExport();const scope=document.getElementById('exportScope');scope.value='full';scope.parentElement.hidden=true;document.querySelector('#exportFormat option[value="xlsx"]').remove();document.querySelector('#modal h2').textContent='Export complete SRS';document.getElementById('modal').className='export-dialog';document.getElementById('modal').oncancel=null;updateExportChoices()};
updateExportChoices=function(){const missing=getExportSections().some(s=>!s.text.trim());document.getElementById('exportGo').disabled=missing;document.getElementById('exportNotice').textContent=missing?'A translated version is not available. Automatic translation is not connected.':'Export the complete SRS. For PDF, choose Save as PDF in the print dialog.'};
const requirementExportPage=blueprintPageRoutes.requirements;
blueprintPageRoutes.requirements=function(){return requirementExportPage().replace('<div class="story-list">','<div class="story-list">')+'<div class="page-actions">'+button('Export requirements · Excel','openRequirementsExport()')+'</div>'};
function openRequirementsExport(){const box=document.getElementById('modal');box.className='export-dialog';box.oncancel=null;box.innerHTML='<div class="history-heading"><div><h2>Export requirements</h2><p class="sub">Excel workbook (.xlsx)</p></div></div><div class="form"><label class="field">Language<select id="reqExportLang" onchange="checkRequirementExport()"><option value="en">English</option><option value="ja">日本語</option></select></label><p id="reqExportNotice" class="sub"></p></div><div class="form-footer"><button onclick="document.getElementById(\'modal\').close()">Cancel</button><button id="reqExportGo" class="primary" onclick="saveRequirementsExcel()">Export Excel</button></div>';box.showModal();checkRequirementExport()}
function requirementExportRows(){const lang=document.getElementById('reqExportLang').value;return backlog().rows.map(r=>({id:r.id,name:lang==='ja'?(r.nameJa||(/[\u3040-\u30ff\u3400-\u9fff]/.test(r.story)?r.story:'')):r.story,module:lang==='ja'?(r.moduleJa||(/[\u3040-\u30ff\u3400-\u9fff]/.test(r.module)?r.module:'')):r.module,priority:r.priority,status:r.status||'Draft'}))}
function checkRequirementExport(){const missing=requirementExportRows().some(r=>!r.name||!r.module);document.getElementById('reqExportGo').disabled=missing;document.getElementById('reqExportNotice').textContent=missing?'Japanese requirement content is not available. Automatic translation is not connected.':'Exports requirements from this project with ID, name, module, priority and status.'}
function saveRequirementsExcel(){const lang=document.getElementById('reqExportLang').value,rows=requirementExportRows();if(rows.some(r=>!r.name||!r.module))return;const labels=lang==='ja'?['ID','要件名','モジュール','優先度','ステータス']:['ID','Requirement name','Module','Priority','Status'];const tr={High:'高',Medium:'中',Low:'低',Draft:'下書き',Approved:'承認済み','In review':'レビュー中'};const sheet=XLSX.utils.aoa_to_sheet([labels,...rows.map(r=>[r.id,r.name,r.module,lang==='ja'?(tr[r.priority]||r.priority):r.priority,lang==='ja'?(tr[r.status]||r.status):r.status])]);sheet['!cols']=[{wch:14},{wch:60},{wch:30},{wch:16},{wch:20}];const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,sheet,'Requirements');XLSX.writeFile(book,'BlueprintReq-requirements-'+lang+'.xlsx');toast('Requirements exported.')}
render();
// Choose the recording source before opening its setup.
const newRecordingSetup=recordingDialog;
recordingDialog=function(){const box=document.getElementById('modal');box.className='recording-dialog';box.oncancel=null;box.innerHTML=`<div class="record-heading"><div><h2>Choose meeting source</h2><p class="sub">Choose a recording or the Zoom workspace.</p></div></div><div class="meeting-source-grid"><button class="meeting-source-card" onclick="document.getElementById('modal').close();newRecordingSetup()"><span class="input-icon">${icon('teams')}</span><strong>Record a meeting</strong><span>Set up a new recording and view its transcript.</span></button><button class="meeting-source-card" onclick="openGoogleMeetWorkspace()"><span class="input-icon">${icon('projects')}</span><strong>Zoom meeting</strong><span>Open the meeting workspace with participants and bilingual transcripts.</span></button></div><div class="form-footer"><button onclick="document.getElementById('modal').close()">Cancel</button></div>`;box.showModal()};
function previousMeetSetup(){const box=document.getElementById('modal');box.innerHTML=`<div class="record-heading"><div><h2>Previous Zoom meeting</h2><p class="sub">Select a meeting to open its transcript and translation.</p></div></div><div class="form"><div class="notice">Demo meeting only. Zoom history is not connected.</div><label class="field">Meeting<select id="previousMeet"><option>Product requirements discussion · Sample meeting</option></select></label><p class="sub">This example contains speaker-labelled English and Japanese text.</p></div><div class="form-footer"><button onclick="document.getElementById('modal').close();recordingDialog()">Back</button><button class="primary" onclick="openPreviousMeet()">Open transcript →</button></div>`}
function openPreviousMeet(){clearInterval(demoRecordingTimer);demoRecordingActive=false;demoRecordingCount=jpMeeting.length;demoRecordingTitle='Product requirements discussion · Previous meeting demo';document.getElementById('modal').close();screen='meetings';history.replaceState(null,'','#meetings');render();window.scrollTo(0,0)}
